# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KUVVET VE ETKİLERİ</text>\n  <rect x="35" y="55" width="190" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hareket Üzerindeki Etkiler</text>\n  <text x="130" y="110" text-anchor="middle" font-size="11.5" fill="#334155">• Duran cismi hareket ettirir</text>\n  <text x="130" y="135" text-anchor="middle" font-size="11.5" fill="#334155">• Hareketliyi durdurabilir</text>\n  <text x="130" y="160" text-anchor="middle" font-size="11.5" fill="#334155">• Hızlandırabilir / yavaşlatır</text>\n  <text x="130" y="185" text-anchor="middle" font-size="11.5" fill="#334155">• Yönünü değiştirebilir</text>\n  <rect x="255" y="55" width="190" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Şekil Değiştirme Etkisi</text>\n  <text x="350" y="110" text-anchor="middle" font-size="11.5" fill="#334155">• Bükme, sıkma, germe</text>\n  <text x="350" y="140" text-anchor="middle" font-size="11.5" fill="#16a34a">Esnek Cisimler (Yay, Sünger):</text>\n  <text x="350" y="160" text-anchor="middle" font-size="11" fill="#475569">Kuvvet kalkınca eski haline döner</text>\n  <text x="350" y="185" text-anchor="middle" font-size="11.5" fill="#b91c1c">Esnek Olmayan (Oyun Hamuru):</text>\n  <text x="350" y="205" text-anchor="middle" font-size="11" fill="#475569">Kalıcı şekil değişikliği kalır</text>\n  <rect x="475" y="55" width="190" height="180" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Kuvvetin Birimi ve Sembolü</text>\n  <text x="570" y="120" text-anchor="middle" font-size="20" font-weight="bold" fill="#854d0e">F (Kuvvet)</text>\n  <text x="570" y="155" text-anchor="middle" font-size="14" font-weight="bold" fill="#1e293b">Birimi: Newton (N)</text>\n  <text x="570" y="185" text-anchor="middle" font-size="11" fill="#475569">Isaac Newton anısına verilmiştir.</text>\n  <text x="570" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#ca8a04">Ölçüm: Dinamometre</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DİNAMOMETRE VE YAYIN ESNEKLİK PRENSİBİ</text>\n  <rect x="40" y="60" width="280" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="180" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Dinamometrenin Yapısı</text>\n  <text x="60" y="115" font-size="11.5" fill="#334155">• İçerisinde esnek sarmal yay bulunur.</text>\n  <text x="60" y="140" font-size="11.5" fill="#334155">• Uygulanan kuvvetle yay uzar.</text>\n  <text x="60" y="165" font-size="11.5" fill="#334155">• Uzama miktarı kuvvetle doğru orantılıdır.</text>\n  <text x="60" y="195" font-size="11.5" font-weight="bold" fill="#2563eb">• Eşit bölmelendirilmiş skala okunur.</text>\n  <rect x="350" y="60" width="310" height="175" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="505" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Hassasiyet ve Ölçüm Sınırı</text>\n  <text x="370" y="115" font-size="11.5" fill="#334155">• İnce yaylı dinamometre: Küçük kuvvetleri</text>\n  <text x="385" y="135" font-size="11" fill="#475569">ölçer, hassastır ancak taşıma kapasitesi azdır.</text>\n  <text x="370" y="165" font-size="11.5" fill="#334155">• Kalın yaylı dinamometre: Büyük kuvvetleri</text>\n  <text x="385" y="185" font-size="11" fill="#475569">ölçer, hassasiyeti düşüktür.</text>\n  <text x="505" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">Dikkat: Yay esneklik sınırını aşmamalıdır!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BİLİM TARİHİNDE KUVVET VE AĞIRLIK: EL-HÂZİNÎ VE BÎRÛNÎ</text>\n  <rect x="40" y="60" width="300" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="190" y="85" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">El-Hâzinî (Mîzânü\'l-Hikme)</text>\n  <text x="60" y="115" font-size="11.5" fill="#334155">• Yer çekimi fikrini Newton\'dan yüzyıllar</text>\n  <text x="75" y="135" font-size="11" fill="#475569">önce dile getiren Müslüman bilim insanıdır.</text>\n  <text x="60" y="160" font-size="11.5" fill="#334155">• \'Hikmet Terazisi\' adıyla hassas hidrostatik</text>\n  <text x="75" y="180" font-size="11" fill="#475569">terazi geliştirmiştir.</text>\n  <text x="60" y="205" font-size="11.5" font-weight="bold" fill="#16a34a">• Cisimlerin yer merkezine çekildiğini açıkladı.</text>\n  <rect x="360" y="60" width="300" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="510" y="85" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">Bîrûnî (Gök Cisimleri ve Çekim)</text>\n  <text x="380" y="115" font-size="11.5" fill="#334155">• \'Dünya dönüyorsa ağaçlar ve taşlar neden</text>\n  <text x="395" y="135" font-size="11" fill="#475569">fırlamıyor?\' sorusunu araştırmıştır.</text>\n  <text x="380" y="165" font-size="11.5" fill="#334155">• Dünyanın merkezindeki çekim kuvvetinin</text>\n  <text x="395" y="185" font-size="11" fill="#475569">her şeyi kendine bağladığını ifade etti.</text>\n  <text x="510" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Bilimin gelişimine öncülük etmişlerdir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
